const key = $env.PPA_PLAUD_WEBHOOK_KEY;
const headers = $json.headers || {};
const suppliedKey = headers['x-ppa-plaud-key'] || headers['X-PPA-Plaud-Key'];
return [{ json: { authorized: Boolean(key) && suppliedKey === key, body: $json.body || {} } }];

const body = $json.body || {};
const read = (...paths) => { for (const path of paths) { const value = path.split('.').reduce((item, part) => item && item[part], body); if (value !== undefined && value !== null && value !== '') return value; } return null; };
const hash = (value) => { let result = 2166136261; for (const char of String(value)) result = Math.imul(result ^ char.charCodeAt(0), 16777619); return (result >>> 0).toString(16); };
const rawType = String(read('event_type', 'trigger_type', 'type', 'event.type') || '').toLowerCase();
const eventType = rawType.includes('summary') ? 'meeting_summary_ready' : rawType.includes('transcript') ? 'meeting_transcript_ready' : null;
if (!eventType) throw new Error('Unsupported Plaud trigger type');
const externalId = read('recording_id', 'recordingId', 'recording.id', 'file_id', 'fileId');
if (!externalId) throw new Error('Plaud recording identifier is required');
const transcript = read('transcript', 'transcript_text', 'content.transcript');
const summary = read('summary', 'ai_summary', 'content.summary');
const eventId = read('event_id', 'eventId', 'zap_event_id', 'zapEventId') || `plaud:${externalId}:${eventType}:${hash([read('updated_at', 'updatedAt', 'generated_at', 'generatedAt', 'created_at', 'createdAt') || '', transcript || summary || ''].join('|'))}`;
return [{json: {source: 'plaud', external_event_id: String(eventId), external_id: String(externalId), event_type: eventType, name: read('title', 'name', 'recording_title', 'recording.title'), started_at: read('started_at', 'startedAt', 'recording.started_at'), ended_at: read('ended_at', 'endedAt', 'recording.ended_at'), transcript, summary, participants: read('participants', 'attendees') || [], source_url: read('source_url', 'url', 'recording.url'), raw_payload: body}}];
